<script>
 import {untrack} from 'svelte';
 import {xcodeSession,xcodeSelectedSource,xcodeActiveBuild,xcodeAvailability,xcodeSearchResults,xcodeTreeRows} from './xcode-state.js';
 import {xcodeMenuItems} from './xcode-menus.js';
 import {XCODE_LANGUAGE_HELP} from './xcode-language.js';
 import {highlightXcodeSource} from './xcode-editor.js';
 import './xcode.css';
 let {state: xcodeState,profile,windowId,window,execute,registerView,available=true,active=true,controls}=$props();
 let root,editor,gutter,coloring,error=$state(''),saveName=$state('HelloWorld.xcodeproj.zip'),newPath=$state('Helper.swift');
 let session=$derived(xcodeSession(xcodeState,windowId)),source=$derived(xcodeSelectedSource(session)),build=$derived(xcodeActiveBuild(session)),capability=$derived(xcodeAvailability(profile)),results=$derived(xcodeSearchResults(session)),treeRows=$derived(xcodeTreeRows(session));
 let lines=$derived(source?.text.split('\n')??[]),preview=$derived(session?.runtime?.preview??null),diagnostics=$derived([...(build?.diagnostics??[]),...(session?.runtime?.diagnostics??[])]);
 let highlighted=$derived(highlightXcodeSource(source?.text??'',source?.language??'swift'));
 function syncScroll(actual){if(gutter)gutter.scrollTop=actual.scrollTop;if(coloring){coloring.scrollTop=actual.scrollTop;coloring.scrollLeft=actual.scrollLeft;}}
 async function send(command,payload={}){const r=await execute?.(command,{windowId},payload);error=r?.status==='rejected'?r.error?.message??'Command unavailable.':'';return r;}
 function option(key,value){const next={...session.chooser,[key]:value};if(key==='platform'){next.deploymentTarget=value==='macos'?/high-sierra/u.test(profile.id)?'10.13':/mojave/u.test(profile.id)?'10.14':/sonoma/u.test(profile.id)?'14.0':/golden-gate/u.test(profile.id)?'26.0':'10.14':/high-sierra/u.test(profile.id)?'11.0':/sonoma/u.test(profile.id)?'17.0':/golden-gate/u.test(profile.id)?'26.0':'12.0';if(value==='ios')next.template='app';}send('xcode.chooser',{options:next});}
 function projectOption(key,value){send('xcode.projectOptions',{options:{...session.project,[key]:value}});}
 async function edit(event){const e=event.currentTarget,r=await send('xcode.edit',{source:e.value,selectionStart:e.selectionStart,selectionEnd:e.selectionEnd});if(r?.status==='rejected'&&e===editor&&source)e.value=source.text;}
 function select(event){const e=event.currentTarget;if(source&&(session.selectionStart!==e.selectionStart||session.selectionEnd!==e.selectionEnd))send('xcode.edit',{source:source.text,selectionStart:e.selectionStart,selectionEnd:e.selectionEnd});}
 function keydown(event){if(!(event.metaKey||event.ctrlKey))return;const key=event.key.toLowerCase();if(['s','b','r','f'].includes(key)){event.preventDefault();send(key==='s'?'xcode.save':key==='b'?'xcode.build':key==='r'?'xcode.run':'xcode.navigator',key==='f'?{navigator:'search'}:{});}}
 function drop(event){const fileId=event.dataTransfer?.getData('application/x-jesteros-file-id');if(fileId){event.preventDefault();send(session.project?'xcode.addFile':'xcode.open',{fileId});}}
 function jumpDiagnostic(d){const s=session.sources.find(s=>s.id===d.fileId||s.fileId===d.fileId||s.id===d.sourceId);if(s)send('xcode.selectSource',{sourceId:s.id,line:d.line});}
 $effect(()=>{const id=windowId,originalRoot=root,originalState=xcodeState,originalSession=untrack(()=>xcodeSession(xcodeState,id));if(!originalRoot||!originalSession||typeof registerView!=='function')return;const mounted=()=>untrack(()=>root===originalRoot&&originalRoot.isConnected&&xcodeState===originalState&&xcodeSession(xcodeState,id)===originalSession&&available===true);const facade={available:mounted,focus(controlId,guard){if(guard?.()!==true||!mounted())return false;const e=Array.from(originalRoot.querySelectorAll('[data-control]')).find(e=>e.dataset.control===controlId);if(!e||e.disabled)return false;e.focus();return guard()===true&&mounted()&&document.activeElement===e;},scroll({top},guard){if(guard?.()!==true||!mounted()||!editor)return false;const actual=editor;actual.scrollTop=top;syncScroll(actual);return guard()===true&&mounted()&&editor===actual&&actual.isConnected;},selectSource(guard){if(guard?.()!==true||!mounted()||!editor)return false;editor.focus();editor.setSelectionRange(originalSession.selectionStart,originalSession.selectionEnd);return guard()===true&&mounted();}};const unregister=untrack(()=>registerView(id,facade));return ()=>{if(typeof unregister==='function')unregister();};});
 $effect(()=>{if(editor&&source){const start=session.selectionStart,end=session.selectionEnd;if(editor.selectionStart!==start||editor.selectionEnd!==end)editor.setSelectionRange(start,end);}});
</script>
{#if session}
<section bind:this={root} class="xcode-app" class:classic={/high-sierra|mojave/u.test(profile.id)} class:modern={/sonoma|golden-gate/u.test(profile.id)} class:golden={profile.id.includes('golden-gate')} class:windows={profile.id.startsWith('windows11')} class:active aria-label={capability.label} onkeydown={keydown} ondragover={e=>e.preventDefault()} ondrop={drop}>
 {#if profile.id.startsWith('windows11')}<nav class="xcode-menu-bar" aria-label="Local Development menus">{#each xcodeMenuItems(xcodeState,windowId) as menu}<details><summary>{menu.label}</summary><div>{#each menu.items as item}<button disabled={!available||!item.enabled} onclick={()=>send(item.command,item.payload)}>{item.label}</button>{/each}</div></details>{/each}</nav>{/if}
 <header class="xcode-toolbar"><button data-control="run" class="xcode-run" title="Run supported source locally (Command-R)" disabled={!available||!session.project} onclick={()=>send('xcode.run')}>▶</button><button data-control="stop" title="Stop local interpreter" disabled={!available||!session.runtime||!['ready','running','paused'].includes(session.runtime.status)} onclick={()=>send('xcode.stop')}>■</button><button class="xcode-scheme" disabled={!session.project||!available} onclick={()=>send('xcode.panel',{panel:'scheme'})}>▧ {session.project?.name??'No Scheme'} <span>›</span> {session.project?.platform==='ios'?'Local iPhone Preview':'Local Mac Preview'} ▾</button><div class="xcode-activity"><strong>{session.runtime?.status==='paused'?'Paused at local breakpoint':session.runtime?.status==='error'?'Local runtime error':build?build.ok?'Build succeeded — supported local subset':'Build failed':session.project?'Ready':'Welcome to Xcode'}</strong><span>{diagnostics.length?'● '+diagnostics.length+' issues':session.runtime?session.runtime.steps+' interpreted steps':'No host SDK or compiler'}</span></div><button data-control="build" disabled={!available||!session.project} title="Build actual source (Command-B)" onclick={()=>send('xcode.build')}>⚒</button><div class="xcode-pane-switches"><button aria-label="Show Project Navigator" title="Project Navigator" onclick={()=>send('xcode.navigator',{navigator:'project'})}>▤</button><button aria-label="Toggle Debug Area" aria-pressed={session.debugVisible} onclick={()=>send('xcode.debug',{visible:!session.debugVisible})}>▥</button><button aria-label="Toggle Inspector" aria-pressed={session.inspectorVisible} onclick={()=>send('xcode.inspector',{visible:!session.inspectorVisible})}>▨</button></div></header>
 <div class="xcode-workspace" class:inspector-hidden={!session.inspectorVisible}>
 <aside class="xcode-navigator"><div class="xcode-navigator-tabs" role="tablist" aria-label="Navigators">{#each [['project','▣','Project'],['search','⌕','Find'],['issues','△','Issues'],['debug','◇','Debug'],['breakpoints','▰','Breakpoints']] as [id,icon,label]}<button role="tab" title={label+' Navigator'} aria-label={label+' Navigator'} aria-selected={session.navigator===id} onclick={()=>send('xcode.navigator',{navigator:id})}>{icon}</button>{/each}</div>
 {#if session.navigator==='project'}<div class="xcode-project-tree"><strong>▾ <span>▧</span> {session.project?.name??'No Project'}</strong>{#each treeRows as row}{#if row.kind==='group'}<button style:padding-left={(16+row.depth*13)+'px'} aria-expanded={row.expanded} onclick={()=>send('xcode.group',{path:row.path,expanded:!row.expanded})}><span>{row.expanded?'▾':'▸'}</span><span class="xcode-folder-icon">▰</span><span>{row.label}</span></button>{:else}<button style:padding-left={(26+row.depth*13)+'px'} class:selected={source?.id===row.sourceId} data-control={'source-'+row.sourceId} onclick={()=>send('xcode.selectSource',{sourceId:row.sourceId})}><span class="xcode-source-icon">{row.language==='swift'?'S':'m'}</span><span>{row.label}</span>{#if row.fileId}<small title={'Actual File '+row.fileId}>↗</small>{/if}</button>{/if}{/each}<p class="xcode-products">▸ Products</p><span class="xcode-product-local">Local interpreted program</span></div>
 {:else if session.navigator==='search'}<input data-control="search" class="xcode-search" aria-label="Find in Workspace" placeholder="Find in Workspace" value={session.query} oninput={e=>send('xcode.search',{query:e.currentTarget.value})}/><p class="xcode-nav-caption">{results.length} source matches</p>{#each results as r}<button class="xcode-result" onclick={()=>send('xcode.selectSource',{sourceId:r.sourceId,line:r.line})}><strong>{r.path}:{r.line}</strong><code>{r.text}</code></button>{/each}
 {:else if session.navigator==='issues'}<p class="xcode-nav-caption">{diagnostics.length} Issues · Actual local source</p>{#each diagnostics as d}<button class="xcode-result issue" onclick={()=>jumpDiagnostic(d)}><strong>{d.severity==='error'?'●':'▲'} {d.line}:{d.column}</strong><span>{d.message}</span></button>{/each}{#if !diagnostics.length}<p class="xcode-empty">No issues in the selected build.<br/>Unsupported syntax is an error, not host compilation success.</p>{/if}
 {:else if session.navigator==='breakpoints'}<p class="xcode-nav-caption">Local statement breakpoints</p>{#each session.breakpoints as b}<div class="xcode-breakpoint-row"><input type="checkbox" aria-label={'Enable breakpoint line '+b.line} checked={b.enabled} onchange={e=>send('xcode.breakpoint',{sourceId:b.sourceId,line:b.line,enabled:e.currentTarget.checked})}/><button onclick={()=>send('xcode.selectSource',{sourceId:b.sourceId,line:b.line})}>{session.sources.find(s=>s.id===b.sourceId)?.path}:{b.line}</button></div>{/each}{#if !session.breakpoints.length}<p class="xcode-empty">Click a line number to set a breakpoint in actual source.</p>{/if}
 {:else}<p class="xcode-nav-caption">Local Debug Session</p><dl><dt>Status</dt><dd>{session.runtime?.status??'Not running'}</dd><dt>Statement</dt><dd>{session.runtime?.current?session.runtime.current.line+':'+session.runtime.current.column:'—'}</dd><dt>Steps</dt><dd>{session.runtime?.steps??0}</dd></dl>{#each Object.entries(session.runtime?.variables??{}) as [name,value]}<p class="xcode-variable"><strong>{name}</strong> = {JSON.stringify(value)}</p>{/each}{/if}
 <footer><button title="Add existing virtual source File" disabled={!session.project||!available} onclick={()=>send('xcode.addFile')}>＋</button><button title="Remove selected source reference" disabled={!source||!available} onclick={()=>send('xcode.removeSource',{sourceId:source.id})}>−</button><span>{session.sources.length} files</span></footer></aside>
 <main class="xcode-editor-area">{#if session.openSourceIds.length&&(!/high-sierra|mojave/u.test(profile.id)||session.openSourceIds.length>1)}<div class="xcode-editor-tabs" role="tablist" aria-label="Actual source editor tabs">{#each session.openSourceIds as sourceId}{@const tabSource=session.sources.find(s=>s.id===sourceId)}<div class:selected={session.selectedSourceId===sourceId}><button role="tab" aria-selected={session.selectedSourceId===sourceId} title={tabSource.path} onclick={()=>send('xcode.selectSource',{sourceId})}><span class="xcode-source-icon">{tabSource.language==='swift'?'S':'m'}</span>{tabSource.path.split('/').at(-1)}</button><button class="xcode-tab-close" aria-label={'Close '+tabSource.path+' editor tab without removing source'} onclick={()=>send('xcode.closeSource',{sourceId})}>×</button></div>{/each}</div>{/if}<div class="xcode-jump-bar"><span>▧ {session.project?.name??'Workspace'}</span><span>›</span><span>{source?.path??'No Selection'}</span><span class="xcode-edited">{session.dirty?'Edited':''}</span></div>
 {#if source}<div class="xcode-code-shell" style:--xcode-source-size={session.fontSize+'px'}><div bind:this={gutter} class="xcode-gutter" aria-label="Source line breakpoints">{#each lines as line,i}<button class:breakpoint={session.breakpoints.some(b=>b.sourceId===source.id&&b.line===i+1&&b.enabled)} class:current={session.runtime?.current?.sourceId===source.id&&session.runtime.current.line===i+1} title={'Toggle breakpoint at line '+(i+1)} onclick={()=>send('xcode.breakpoint',{sourceId:source.id,line:i+1})}>{i+1}</button>{/each}</div><div class="xcode-source-wrapper"><pre bind:this={coloring} class="xcode-source-coloring" class:wrap={session.wrap} aria-hidden="true"><code>{#each highlighted as span}<span class={'xcode-token-'+span.kind}>{span.text}</span>{/each}</code></pre><textarea bind:this={editor} data-control="editor" aria-label={source.path+' code editor'} spellcheck="false" autocapitalize="off" autocomplete="off" wrap={session.wrap?'soft':'off'} value={source.text} disabled={!available} oninput={edit} onselect={select} onclick={select} onkeyup={select} onscroll={e=>syncScroll(e.currentTarget)}></textarea></div></div>
 {:else}<div class="xcode-no-selection"><strong>{session.project?'No Selection':'Welcome to Xcode'}</strong><span>{session.project?'Add or select a source file.':'Create a new project or open a genuine virtual Xcode project archive.'}</span><button onclick={()=>send('xcode.panel',{panel:'chooser'})}>Create a new Xcode project</button><button onclick={()=>send('xcode.open')}>Open another project…</button></div>{/if}
 {#if session.debugVisible}<section class="xcode-debug-area" aria-label="Local debug area"><div class="xcode-debug-toolbar"><button title="Continue local interpreter" disabled={session.runtime?.status!=='paused'} onclick={()=>send('xcode.continue')}>▶</button><button title="Step one local source statement" disabled={!build?.ok} onclick={()=>send('xcode.step')}>↷</button><strong>{session.runtime?.status??'Debug output'}</strong><span>Local interpreter · not LLDB</span><button onclick={()=>send('xcode.debug',{visible:false})}>×</button></div><div class="xcode-debug-content"><div class="xcode-variables">{#each Object.entries(session.runtime?.variables??{}) as [name,value]}<p><b>{name}</b><code>{JSON.stringify(value)}</code></p>{/each}{#if !Object.keys(session.runtime?.variables??{}).length}<span>No local variables</span>{/if}</div><pre>{session.runtime?.console?.join('\n')??(build?build.ok?'Supported local source parsed. Run to interpret it.':build.diagnostics.map(d=>d.line+':'+d.column+' '+d.message).join('\n'):'Build or run a source to produce actual local output.')}</pre></div></section>{/if}
 <footer class="xcode-editor-status"><span>{source?.language==='objc'?'Objective-C':'Swift'} · UTF-8</span><span>{source?'Ln '+(source.text.slice(0,session.selectionStart).split('\n').length)+' · '+source.text.length+' characters':'No source'}</span><span>{source?.fileId?'File '+source.fileId+' @ '+source.fileRevision:'Unsaved local buffer'}</span></footer></main>
 {#if session.inspectorVisible}<aside class="xcode-inspector"><div class="xcode-inspector-tabs">{#each [['file','▧'],['project','☷'],['history','◷']] as [id,icon]}<button aria-label={id+' inspector'} class:selected={session.inspector===id} onclick={()=>send('xcode.inspector',{inspector:id})}>{icon}</button>{/each}</div>
 {#if session.inspector==='file'}<h3>Identity and Type</h3><dl><dt>Name</dt><dd>{source?.path??'No Selection'}</dd><dt>Type</dt><dd>{source?.language==='objc'?'Objective-C Source':'Swift Source'}</dd><dt>Location</dt><dd>{source?.fileId?'Virtual File reference':'Project archive / buffer'}</dd><dt>File ID</dt><dd>{source?.fileId??'Not separately saved'}</dd><dt>Revision</dt><dd>{source?.revision??'—'}</dd></dl><h3>Target Membership</h3><p>☑ {session.project?.name??'No target'}</p><p class="xcode-inspector-note">Only the local supported subset is interpreted. File revisions and exact buffer text are retained in each build.</p>
 {:else if session.inspector==='project'}<h3>Project Document</h3>{#if session.project}{#each [['name','Project Name'],['organization','Organization'],['bundleIdentifier','Bundle Identifier'],['deploymentTarget','Deployment Target']] as [key,label]}<label>{label}<input aria-label={label} value={session.project[key]} onchange={e=>projectOption(key,e.currentTarget.value)}/></label>{/each}<label>Platform<select value={session.project.platform} onchange={e=>projectOption('platform',e.currentTarget.value)}><option value="ios">iOS (local preview)</option><option value="macos">macOS (local preview)</option></select></label><h3>New Source</h3><input aria-label="New source path" bind:value={newPath}/><button onclick={()=>send('xcode.newSource',{path:newPath,language:newPath.endsWith('.m')?'objc':'swift'})}>Add Source Buffer</button><button onclick={()=>send('xcode.addFile')}>Add Actual File…</button><h3>Build Records</h3>{#each session.builds.toReversed() as b}<p class="xcode-build-record">{b.ok?'✓':'●'} {b.id}<small>{b.sources.length} exact source snapshots · scene {b.time}</small></p>{/each}{/if}
 {:else}<h3>Source History</h3>{#each session.history.toReversed() as h}<button class="xcode-history" onclick={()=>send('xcode.restoreHistory',{entryId:h.id})}><strong>{session.sources.find(s=>s.id===h.sourceId)?.path??'Removed source'}</strong><span>Scene {h.time} · {h.text.length} characters</span></button>{/each}{#if !session.history.length}<p>Source edits retain bounded genuine history.</p>{/if}{/if}</aside>{/if}</div>
 <footer class="xcode-disclosure"><span>{capability.version} · {capability.disclosure}</span><span>{capability.executionDisclosure}</span></footer>
 {#if error}<div class="xcode-error" role="alert">{error}<button onclick={()=>error=''} aria-label="Dismiss error">×</button></div>{/if}
 {#if session.simulatorVisible&&preview}<div class="xcode-simulator-overlay"><section class="xcode-simulator" class:mac-preview={session.project?.platform==='macos'} role="dialog" aria-label="Local interpreted Simulator presentation"><header><strong>{session.project?.platform==='ios'?'iPhone':'Mac'} — Local Simulator Preview</strong><button onclick={()=>send('xcode.simulator',{visible:false})}>×</button></header><p>Interpreted source state · not Apple Simulator</p><div class="xcode-device"><div class="xcode-device-screen" style:background={preview.background}><header>{preview.title}</header><main><p>{preview.text}</p>{#each preview.controls as control}<div class:preview-button={control.kind==='button'} class:preview-label={control.kind==='label'} class:disabled={control.kind==='button'&&!control.enabled}>{control.text}</div>{/each}</main><footer>{session.runtime.status} · {session.runtime.steps} source steps</footer></div></div><small>Preview controls display interpreted values. The subset has no host UI event dispatch.</small></section></div>{/if}
 {#if session.panel!=='none'}<div class="xcode-sheet-shade"><section class="xcode-sheet" class:welcome={session.panel==='chooser'} role="dialog" aria-modal="true" aria-label={'Xcode '+session.panel}>
 {#if session.panel==='chooser'}<div class="xcode-welcome-heading"><div class="xcode-blueprint">⚒</div><h1>{capability.label}</h1><p>Version {capability.version}</p></div><h2>Choose a template for your new project:</h2><div class="xcode-platform-tabs">{#each [['ios','iOS'],['macos','macOS']] as [id,label]}<button class:selected={session.chooser.platform===id} onclick={()=>option('platform',id)}>{label}</button>{/each}</div><p class="xcode-template-category">Application</p><div class="xcode-template-grid"><button class:selected={session.chooser.template==='app'} onclick={()=>option('template','app')}><span>▧</span>{session.chooser.platform==='ios'&&/high-sierra|mojave/u.test(profile.id)?'Single View App':'App'}<small>Explicit local preview source</small></button>{#if session.chooser.platform==='macos'}<button class:selected={session.chooser.template==='command-line'} onclick={()=>option('template','command-line')}><span>▣</span>Command Line Tool<small>Actual console expressions</small></button>{/if}</div><p>These templates use the documented local language subset, not a host SDK.</p><div class="xcode-sheet-actions"><button onclick={()=>send('xcode.open')}>Open Project…</button><button onclick={()=>send('xcode.panel',{panel:'options'})}>Next</button></div>
 {:else if session.panel==='options'}<h2>Choose options for your new project:</h2>{#each [['name','Product Name'],['organization','Organization Name'],['bundleIdentifier','Bundle Identifier'],['deploymentTarget','Deployment Target']] as [key,label]}<label>{label}<input data-control={'project-'+key} value={session.chooser[key]} oninput={e=>option(key,e.currentTarget.value)}/></label>{/each}<label>Language<select value={session.chooser.language} onchange={e=>option('language',e.currentTarget.value)}><option value="swift">Swift (local subset)</option><option value="objc">Objective-C (local subset)</option></select></label><p>Project is saved as a genuine ZIP containing OpenStep project.pbxproj, .xcscheme, workspace XML and actual source text. No git repository or host SDK is created.</p><div class="xcode-sheet-actions"><button onclick={()=>send('xcode.panel',{panel:'chooser'})}>Previous</button><button onclick={()=>send('xcode.createProject')}>Create</button></div>
 {:else if session.panel==='save'}<h2>Save Xcode Project</h2><label>Save As<input data-control="save-name" bind:value={saveName}/></label><p>Genuine .xcodeproj.zip with native project, scheme/workspace XML and source files. Saving is atomic with the virtual File and owner revision.</p><button onclick={()=>send('xcode.save',{name:saveName,saveAs:true})}>Save Project</button>
 {:else if session.panel==='scheme'}<h2>Edit Scheme — {session.project?.name}</h2><dl><dt>Build</dt><dd>{session.sources.length} actual source files</dd><dt>Run</dt><dd>Bounded local interpreter</dd><dt>Executable</dt><dd>Interpreted program · no host binary</dd><dt>Destination</dt><dd>{session.project?.platform==='ios'?'Local iPhone presentation':'Local Mac presentation'}</dd><dt>Configuration</dt><dd>Debug · source-aware diagnostics</dd></dl><button onclick={()=>send('xcode.build')}>Build</button><button onclick={()=>send('xcode.run')}>Run</button><p>The saved .xcscheme uses native XML, not an invented JSON scheme.</p>
 {:else if session.panel==='settings'}<h2>Xcode {(/sonoma|golden-gate/u.test(profile.id))?'Settings':'Preferences'}</h2><h3>Text Editing</h3><label>Font Size<input type="number" min="10" max="24" value={session.fontSize} onchange={e=>send('xcode.settings',{fontSize:Number(e.currentTarget.value)})}/></label><label><input type="checkbox" checked={session.wrap} onchange={e=>send('xcode.settings',{wrap:e.currentTarget.checked})}/> Wrap lines</label><p>Host accounts, signing certificates, SDK locations, source control and devices are deliberately not claimed.</p>
 {:else if session.panel==='help'}<h2>Local Development Language Reference</h2><pre class="xcode-language-help">{typeof XCODE_LANGUAGE_HELP==='string'?XCODE_LANGUAGE_HELP:JSON.stringify(XCODE_LANGUAGE_HELP,null,2)}</pre>
 {:else if session.panel==='close'}<h2>Save changes to {session.title}?</h2><p>Your actual unsaved source changes will be lost if you don’t save.</p><div class="xcode-sheet-actions"><button onclick={()=>send('xcode.closeDecision',{decision:'discard'})}>Don’t Save</button><button onclick={()=>send('xcode.closeDecision',{decision:'cancel'})}>Cancel</button><button onclick={()=>send('xcode.closeDecision',{decision:'save'})}>Save</button></div>{/if}
 {#if session.panel!=='close'}<button class="xcode-sheet-done" onclick={()=>send('xcode.panel',{panel:'none'})}>Cancel / Done</button>{/if}</section></div>{/if}
</section>{/if}
